import{_ as t}from"./chunks/pilotage.FGz03KRv.js";import{_ as o}from"./chunks/coupe.64JYIVTF.js";import{_ as a,o as n,c as r,a2 as s}from"./chunks/framework.CQxpk36T.js";const b=JSON.parse('{"title":"Tour of the interface","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface.md","filePath":"en/interface.md","lastUpdated":1793574169000}'),i={name:"en/interface.md"};function h(l,e,d,g,p,u){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tour-of-the-interface" tabindex="-1">Tour of the interface <a class="header-anchor" href="#tour-of-the-interface" aria-label="Permalink to &quot;Tour of the interface&quot;">​</a></h1><p>The interface fits a phone held in one hand, and spreads out on a tablet or computer. It has three tabs: <strong>Maison</strong> (home), <strong>Tableau</strong> (dashboard) and <strong>Énergie</strong> (energy), at the bottom of the screen on a phone, at the top on a computer.</p><h2 id="the-top-bar" tabindex="-1">The top bar <a class="header-anchor" href="#the-top-bar" aria-label="Permalink to &quot;The top bar&quot;">​</a></h2><figure class="haven-shot"><img src="'+t+'" alt="The selected house, with the top bar and the rooms panel"><figcaption><strong>Top bar</strong>: property name, time, weather and people at home on the left; labels, editor and settings on the right.</figcaption></figure><p>On the left:</p><ul><li>the <strong>property name</strong>;</li><li>the scene <strong>time</strong>: a tap opens the <a href="#time-and-weather">time control</a>;</li><li>the <strong>weather</strong> and temperature: a tap opens the details;</li><li><strong>one initial per person at home</strong> (Home Assistant <code>person.*</code> entities).</li></ul><p>On the right, on the Maison tab:</p><ul><li>the <strong>tag</strong> shows or hides the floating labels above the rooms;</li><li>the <strong>pencil</strong> opens the <a href="/HAven-docs/en/guide/editeur">in-page editor</a>;</li><li>the <strong>badge</strong> opens the <a href="#settings">settings</a>. Its colour shows the connection state: Démo (demo), Home Assistant, Connexion… (connecting) or Hors ligne (offline).</li></ul><h2 id="the-maison-tab" tabindex="-1">The Maison tab <a class="header-anchor" href="#the-maison-tab" aria-label="Permalink to &quot;The Maison tab&quot;">​</a></h2><p>The 3D view. One finger rotates the model, two fingers zoom and pan (with a mouse: drag to rotate, wheel to zoom towards the pointer, right-click to pan).</p><ul><li><strong>Nothing selected</strong>: a summary lists the buildings with the number of lit rooms, solar production and the cars (parked or away). Tapping a line selects the building. The <strong>Vue d&#39;ensemble</strong> (overview) button frames the whole property.</li><li><strong>A building tapped</strong>: the camera moves closer, the other buildings fade, and its <strong>panel</strong> opens with its rooms, floor by floor: lights, temperatures, heating, shutters, doors, vehicles, solar panels.</li><li><strong>A room tapped</strong> (on the model, in the panel or on its label): everything turns off if one of its lamps is on, everything turns on otherwise.</li></ul><h3 id="the-cutaway-view" tabindex="-1">The cutaway view <a class="header-anchor" href="#the-cutaway-view" aria-label="Permalink to &quot;The cutaway view&quot;">​</a></h3><p>When the building has <a href="/HAven-docs/en/guide/plans">floor plans</a>, its panel offers <strong>Extérieur / RDC / Étage</strong> (outside / ground floor / upper floor). The roof disappears and the chosen floor appears as a furnished dollhouse; neighbouring buildings are cut at the same height. Floors are tinted by each room&#39;s temperature (bluish below 20 °C, orange above 21 °C) and a little flame shows heating that is running. Rooms stay in the half-light of an interior; a lit room is bathed in the warm light of its ceiling lamp, brightest under the lamp and soft towards the corners, which also lights its walls and furniture. Tapping a room turns its lights on or off.</p><p><img src="'+o+'" alt="Cutaway view of the ground floor"></p><h2 id="the-tableau-and-energie-tabs" tabindex="-1">The Tableau and Énergie tabs <a class="header-anchor" href="#the-tableau-and-energie-tabs" aria-label="Permalink to &quot;The Tableau and Énergie tabs&quot;">​</a></h2><ul><li><strong><a href="/HAven-docs/en/home-assistant/tableau">Tableau</a></strong> (dashboard): one tile per device, sorted by building then room, with scenes, favourites and search.</li><li><strong><a href="/HAven-docs/en/home-assistant/energie">Énergie</a></strong> (energy): live flows, the day&#39;s totals and curve, battery, electric car and the devices using power.</li></ul><h2 id="time-and-weather" tabindex="-1">Time and weather <a class="header-anchor" href="#time-and-weather" aria-label="Permalink to &quot;Time and weather&quot;">​</a></h2><p>The <strong>time control</strong> plays through the day (play button) or picks a precise time and day: the sun, moon, shadows and season follow. Simulated time is shown in colour in the bar; <strong>Maintenant</strong> (now) returns to the real time.</p><p>The <strong>weather</strong> comes from <a href="https://open-meteo.com" target="_blank" rel="noreferrer">Open-Meteo</a>: free, no key, refreshed every 10 minutes. The position sent is rounded to about 1 km. Without internet access, HAven uses Home Assistant&#39;s first <code>weather.*</code> entity.</p><p>After sunset, the interface darkens by itself so it doesn&#39;t dazzle.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The badge at the top right opens the settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td>Adresse de Home Assistant</td><td><strong>Se connecter</strong> (connect) to Home Assistant, or <strong>Rester en démo</strong> (stay in demo) (<a href="/HAven-docs/en/home-assistant/">details</a>)</td></tr><tr><td>Météo</td><td>Live, or a weather preset in demo mode</td></tr><tr><td>Propriété</td><td><strong>Éditer</strong> (edit) the property, or <strong>Relever une position</strong> (pick a position) to describe doors and windows</td></tr><tr><td>Qualité graphique</td><td>Auto, Haute (high), Moyenne (medium) or Économe (saver)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Graphics quality</p><p><strong>Auto</strong> measures how long each frame takes and adjusts resolution and effects. Post-processing effects (glow, outline, tilt-shift blur) are only on in high quality. <strong>Économe</strong> spares the battery of an old phone or a wall tablet.</p></div><h2 id="install-on-the-home-screen" tabindex="-1">Install on the home screen <a class="header-anchor" href="#install-on-the-home-screen" aria-label="Permalink to &quot;Install on the home screen&quot;">​</a></h2><p>HAven is an installable web app:</p><ul><li><strong>iPhone, iPad</strong>: Safari → Share → &quot;Add to Home Screen&quot;;</li><li><strong>Android</strong>: Chrome → menu → &quot;Install app&quot;;</li><li><strong>Computer</strong>: the install icon in the Chrome or Edge address bar.</li></ul><p>It then opens full screen, without a browser bar. For instant offline opening, it must be served over HTTPS: see <a href="/HAven-docs/en/hebergement#https">Hosting</a>.</p>',28)])])}const w=a(i,[["render",h]]);export{b as __pageData,w as default};
